-- Applied to sfykcmbgsuzlyksosjny as 20261001123923 v1_core_content_architecture.
-- Canonical source retained here for version control.
create extension if not exists pgcrypto;
create type public.content_status as enum ('draft','in_review','scheduled','published','archived');
create type public.media_kind as enum ('image','video','youtube','instagram','facebook','x','other');
create type public.entity_kind as enum ('movie','person','company','news_article','gallery','video','short_film','ott_title','review','box_office','poll','contest');
create type public.credit_kind as enum ('actor','director','producer','writer','music_director','cinematographer','editor','singer','other');
create table public.movies(id uuid primary key default gen_random_uuid(),slug text not null unique,title_en text not null,title_te text,synopsis_en text,synopsis_te text,release_date date,runtime_minutes int check(runtime_minutes is null or runtime_minutes>0),certificate text,language_code text default 'te',country_code text default 'IN',poster_url text,backdrop_url text,status public.content_status not null default 'draft',seo_title_en text,seo_title_te text,seo_description_en text,seo_description_te text,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.people(id uuid primary key default gen_random_uuid(),slug text not null unique,name_en text not null,name_te text,bio_en text,bio_te text,date_of_birth date,date_of_death date,gender text,primary_profession text,profile_image_url text,birthplace_en text,birthplace_te text,status public.content_status not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.companies(id uuid primary key default gen_random_uuid(),slug text not null unique,name_en text not null,name_te text,description_en text,description_te text,company_type text,founded_year int,logo_url text,website_url text,status public.content_status not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.movie_credits(id uuid primary key default gen_random_uuid(),movie_id uuid not null references public.movies(id) on delete cascade,person_id uuid not null references public.people(id) on delete cascade,credit_type public.credit_kind not null,character_name_en text,character_name_te text,billing_order int,created_at timestamptz not null default now(),unique(movie_id,person_id,credit_type,character_name_en));
create table public.movie_companies(movie_id uuid not null references public.movies(id) on delete cascade,company_id uuid not null references public.companies(id) on delete cascade,relationship_type text not null default 'production',primary key(movie_id,company_id,relationship_type));
create table public.news_articles(id uuid primary key default gen_random_uuid(),slug text not null unique,headline_en text not null,headline_te text,dek_en text,dek_te text,body_en text,body_te text,hero_image_url text,category text,source_name text,source_url text,status public.content_status not null default 'draft',is_breaking boolean not null default false,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.image_galleries(id uuid primary key default gen_random_uuid(),slug text not null unique,title_en text not null,title_te text,description_en text,description_te text,cover_image_url text,status public.content_status not null default 'draft',published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.gallery_images(id uuid primary key default gen_random_uuid(),gallery_id uuid not null references public.image_galleries(id) on delete cascade,image_url text not null,alt_en text,alt_te text,caption_en text,caption_te text,sort_order int not null default 0,credit text,created_at timestamptz not null default now());
create table public.videos(id uuid primary key default gen_random_uuid(),slug text not null unique,title_en text not null,title_te text,description_en text,description_te text,platform public.media_kind not null default 'video',external_id text,video_url text,thumbnail_url text,duration_seconds int,status public.content_status not null default 'draft',published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.short_films(id uuid primary key default gen_random_uuid(),slug text not null unique,title_en text not null,title_te text,synopsis_en text,synopsis_te text,video_id uuid references public.videos(id) on delete set null,director_id uuid references public.people(id) on delete set null,release_date date,poster_url text,status public.content_status not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.ott_platforms(id uuid primary key default gen_random_uuid(),slug text not null unique,name_en text not null,name_te text,logo_url text,website_url text,created_at timestamptz not null default now());
create table public.ott_titles(id uuid primary key default gen_random_uuid(),slug text not null unique,title_en text not null,title_te text,synopsis_en text,synopsis_te text,content_type text not null default 'movie',movie_id uuid references public.movies(id) on delete set null,release_date date,seasons int,status public.content_status not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.ott_availability(id uuid primary key default gen_random_uuid(),ott_title_id uuid not null references public.ott_titles(id) on delete cascade,platform_id uuid not null references public.ott_platforms(id) on delete cascade,region_code text not null default 'IN',watch_url text,available_from date,available_until date,unique(ott_title_id,platform_id,region_code));
create table public.reviews(id uuid primary key default gen_random_uuid(),slug text not null unique,movie_id uuid references public.movies(id) on delete cascade,ott_title_id uuid references public.ott_titles(id) on delete cascade,title_en text not null,title_te text,body_en text,body_te text,rating numeric(3,1) check(rating is null or rating between 0 and 10),verdict_en text,verdict_te text,status public.content_status not null default 'draft',published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(movie_id is not null or ott_title_id is not null));
create table public.box_office(id uuid primary key default gen_random_uuid(),movie_id uuid not null references public.movies(id) on delete cascade,territory text not null,period_type text not null default 'daily',period_start date not null,period_end date,gross_amount numeric(18,2),net_amount numeric(18,2),distributor_share numeric(18,2),currency_code char(3) not null default 'INR',source_name text,source_url text,is_estimate boolean not null default true,created_at timestamptz not null default now(),unique(movie_id,territory,period_type,period_start));
create table public.polls(id uuid primary key default gen_random_uuid(),slug text not null unique,question_en text not null,question_te text,description_en text,description_te text,starts_at timestamptz,ends_at timestamptz,status public.content_status not null default 'draft',allow_multiple boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.poll_options(id uuid primary key default gen_random_uuid(),poll_id uuid not null references public.polls(id) on delete cascade,label_en text not null,label_te text,sort_order int not null default 0,created_at timestamptz not null default now());
create table public.poll_votes(id uuid primary key default gen_random_uuid(),poll_id uuid not null references public.polls(id) on delete cascade,option_id uuid not null references public.poll_options(id) on delete cascade,voter_key_hash text,created_at timestamptz not null default now());
create table public.contests(id uuid primary key default gen_random_uuid(),slug text not null unique,title_en text not null,title_te text,description_en text,description_te text,rules_en text,rules_te text,starts_at timestamptz,ends_at timestamptz,status public.content_status not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.contest_entries(id uuid primary key default gen_random_uuid(),contest_id uuid not null references public.contests(id) on delete cascade,participant_name text,participant_email text,participant_phone text,payload jsonb not null default '{}'::jsonb,status text not null default 'submitted',created_at timestamptz not null default now());
create table public.tags(id uuid primary key default gen_random_uuid(),slug text not null unique,name_en text not null,name_te text,created_at timestamptz not null default now());
create table public.entity_registry(id uuid primary key default gen_random_uuid(),entity_type public.entity_kind not null,entity_id uuid not null,canonical_slug text not null,created_at timestamptz not null default now(),unique(entity_type,entity_id),unique(entity_type,canonical_slug));
create table public.entity_relations(id uuid primary key default gen_random_uuid(),from_entity_id uuid not null references public.entity_registry(id) on delete cascade,to_entity_id uuid not null references public.entity_registry(id) on delete cascade,relation_type text not null,sort_order int not null default 0,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(from_entity_id,to_entity_id,relation_type));
create table public.entity_tags(entity_id uuid not null references public.entity_registry(id) on delete cascade,tag_id uuid not null references public.tags(id) on delete cascade,primary key(entity_id,tag_id));
create table public.editorial_items(id uuid primary key default gen_random_uuid(),entity_id uuid not null unique references public.entity_registry(id) on delete cascade,workflow_status public.content_status not null default 'draft',priority int not null default 0,assigned_editor_ref text,notes text,scheduled_for timestamptz,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.editorial_revisions(id uuid primary key default gen_random_uuid(),editorial_item_id uuid not null references public.editorial_items(id) on delete cascade,revision_no int not null,snapshot jsonb not null,change_note text,editor_ref text,created_at timestamptz not null default now(),unique(editorial_item_id,revision_no));
create table public.movie_pulse(id uuid primary key default gen_random_uuid(),movie_id uuid not null references public.movies(id) on delete cascade,captured_at timestamptz not null default now(),window_label text not null default '24h',news_mentions int not null default 0,video_views bigint not null default 0,social_mentions int not null default 0,poll_votes int not null default 0,sentiment_score numeric(5,2),trend_score numeric(8,2),source_payload jsonb not null default '{}'::jsonb,unique(movie_id,captured_at,window_label));
create index movie_credits_movie_idx on public.movie_credits(movie_id); create index movie_credits_person_idx on public.movie_credits(person_id); create index news_articles_published_idx on public.news_articles(status,published_at desc); create index gallery_images_gallery_idx on public.gallery_images(gallery_id,sort_order); create index videos_published_idx on public.videos(status,published_at desc); create index box_office_movie_period_idx on public.box_office(movie_id,period_start desc); create index entity_relations_from_idx on public.entity_relations(from_entity_id,relation_type); create index entity_relations_to_idx on public.entity_relations(to_entity_id,relation_type); create index movie_pulse_movie_time_idx on public.movie_pulse(movie_id,captured_at desc);
do $$ declare t text; begin foreach t in array array['movies','people','companies','movie_credits','movie_companies','news_articles','image_galleries','gallery_images','videos','short_films','ott_platforms','ott_titles','ott_availability','reviews','box_office','polls','poll_options','poll_votes','contests','contest_entries','tags','entity_registry','entity_relations','entity_tags','editorial_items','editorial_revisions','movie_pulse'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on table public.%I from anon, authenticated',t); end loop; end $$;